def min_cost_to_paint_white(n, m, rectangles):
    # Convert input to a list of sets representing columns with black cells
    black_columns = [set() for _ in range(n + 1)]

    for x1, y1, x2, y2 in rectangles:
        for x in range(x1 - 1, x2):
            for y in range(y1 - 1, y2):
                black_columns[x].add(y)

    # Calculate the cost to paint each column
    total_cost = 0
    for black in black_columns:
        if black:
            h = max(black) - min(black) + 1
            w = len(black)
            total_cost += min(h, w)

    return total_cost

